<?php
namespace App\Http\Controllers;
use App\Models\{Quiz,QuizAttempt,Enrollment}; use App\Services\LearningAccessService; use Illuminate\Http\Request;
class QuizController extends Controller {
 public function index(Request $r){$programIds=Enrollment::where('user_id',$r->user()->id)->where('status','active')->pluck('program_id');$quizzes=Quiz::withCount(['attempts as my_attempts'=>fn($q)=>$q->where('user_id',$r->user()->id)])->where('is_active',1)->whereIn('program_id',$programIds)->get();return view('quizzes.index',compact('quizzes'));}
 public function show(Request $r,Quiz $quiz,LearningAccessService $access){$this->allow($r,$quiz,$access);$quiz->load('questions.options');return view('quizzes.show',compact('quiz'));}
 public function submit(Request $r,Quiz $quiz,LearningAccessService $access){$this->allow($r,$quiz,$access);$used=QuizAttempt::where('quiz_id',$quiz->id)->where('user_id',$r->user()->id)->count();if($quiz->attempt_limit!==null&&$used >= $quiz->attempt_limit)return back()->withErrors(['quiz'=>'Лимит попыток исчерпан.']);$quiz->load('questions.options');$answers=$r->input('answers',[]);$score=0;$max=0;foreach($quiz->questions as $q){$max+=(float)$q->points;$selected=(array)($answers[$q->id]??[]);$correct=$q->options->where('is_correct',true)->pluck('id')->map(fn($v)=>(string)$v)->sort()->values()->all();$given=collect($selected)->map(fn($v)=>(string)$v)->sort()->values()->all();if($given===$correct)$score+=(float)$q->points;}$percent=$max>0?round($score/$max*100,2):0;$a=QuizAttempt::create(['quiz_id'=>$quiz->id,'user_id'=>$r->user()->id,'score'=>$score,'percent'=>$percent,'passed'=>$percent >= $quiz->pass_percent,'answers'=>$answers,'started_at'=>now(),'finished_at'=>now(),'ip'=>$r->ip()]);return redirect()->route('quizzes.index')->with('ok',($a->passed?'Тест пройден: ':'Тест не пройден: ').$percent.'%');}
 private function allow(Request $r,Quiz $q,LearningAccessService $access):void{$access->enrollment($r->user(),$q->program_id);if($q->learning_section_id){$s=$q->learningSection;if($s&&!$access->canOpenSection($r->user(),$s))abort(403,'Предыдущий раздел ещё не завершён.');}}
}